# pythom -m pip install cryptography
from cryptography.fernet import Fernet

def generate_key() -> bytes:
    """Generates a secure key. Save this key to encrypt/decrypt later."""
    return Fernet.generate_key()


def encrypt_message(message: str, key: bytes) -> bytes:
    """Encrypts plaintext using the provided key."""
    f = Fernet(key)
    return f.encrypt(message.encode("utf-8"))


def decrypt_message(encrypted_message: bytes, key: bytes) -> str:
    """Decrypts ciphertext back to plaintext using the provided key."""
    f = Fernet(key)
    return f.decrypt(encrypted_message).decode("utf-8")


